import org.jlinalg.genetics.LofteeVcfAudit;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

/** Closed unchanged-original LOFTEE execution with complete native auditing and atomic result admission. */
public final class LofteeWorkflowCli {
    private LofteeWorkflowCli() { }
    static final String ACTION="Require exit0 AND analysis-status.json result_admitted=true. Read WARNINGS.md, all original stdout/stderr/warnings, process cleanup receipts, input/runtime identities and complete native variant/annotation ledgers. SKIP3: dependent analysis skipped; prepare exact permitted Linux x86_64 dependencies/resources or keep that analysis skipped. Analysis installs nothing. FAIL2: no result from this atomic batch is admitted, including earlier completed cases. Preserve every original input, failed attempt and provisional ledger; correct the named data/source/index/runtime/permission/capacity/timeout cause and retry NEW paths. Never repair IDs/alleles, drop variants/transcripts, impute HC/LC, replace NaN/Inf, or infer assembly/release/transcript selection. Original flags and non-target empty confidence remain distinct. No paper reproduction, canonical/released availability or whole-goal completion is inferred.";
    public static void main(String[] args){System.exit(run(args,System.out,System.err));}
    static int run(String[] args,PrintStream output,PrintStream error) {
        if(args.length==1&&args[0].equals("--help")){emit(output,"LofteeWorkflowCli --request REQUEST.json\nOriginal VEP105.0/LOFTEE GRCh38 development workflow; exact permitted runtime required. Native audit is portable; upstream execution requires Linux x86_64.\n"+ACTION);return 0;}
        try{
            require(args.length==2&&args[0].equals("--request"),"Use --request FILE or --help");Path requestPath=Path.of(args[1]).toAbsolutePath().normalize();byte[] raw=NextflowFiles.bytes(requestPath,1048576);var requestPin=NextflowFiles.pin(requestPath,1048576,()->{});require(raw.length==requestPin.bytes()&&NextflowFiles.sha(raw).equals(requestPin.sha256()),"Request changed between capture and parsing");var r=LofteeWorkflowRequest.parse(object(NextflowParameters.parse(NextflowFiles.utf8(raw),1048576,100000)),requestPath.getParent());Path out=resolved(r.out());require(!Files.exists(out,LinkOption.NOFOLLOW_LINKS),"Output already exists; choose a NEW directory");
            for(Path directory:r.runtime().values()){Path root=resolved(directory);require(!out.startsWith(root)&&!root.startsWith(out),"Output overlaps declared runtime/source; preserve existing dependencies and choose a separate NEW output");}
            if(r.transcripts().get("kind").equals("vep-cache")){Path cache=resolved(Path.of(text(r.transcripts().get("directory"))));require(!out.startsWith(cache)&&!cache.startsWith(out),"Output overlaps original cache");}
            int[] exit={2};transaction(out,(stage,manifest)->{
                Files.write(stage.resolve("request.original.json"),raw,StandardOpenOption.CREATE_NEW);NextflowFiles.writeJson(stage.resolve("effective-request.json"),r.effective());var state=new LinkedHashMap<String,Object>();state.put("status","RUNNING_NO_RESULT_ADMITTED");state.put("result_admitted",false);state.put("required_action",ACTION);writeStatus(stage,state);var warnings=new ArrayList<String>();warnings.add(ACTION);warnings.add("Original LOFTEE confidence and VEP consequence fitting remain upstream. Native checks preserve complete returned families and exact input REF/identity; they do not independently certify biological transcript completeness, reference provenance, paper masks/corrections, or HC/LC calibration.");var reports=new ArrayList<Map<String,Object>>();
                try{
                    LofteeWorkflowRuntime.quick(r);require(stage.toString().matches("/[A-Za-z0-9_./-]+"),"Original LOFTEE shell calls require a portable ASCII output-parent path with only letters, digits, slash, dot, underscore and hyphen. Choose a NEW safe output path; input paths are captured without renaming their biological identifiers.");
                    progress(stage,state,error,"Checking and capturing all input/reference files");var inputs=LofteeWorkflowInputs.prepare(stage,r,warnings);progress(stage,state,error,"Checking complete original runtime and source bytes");var runtime=LofteeWorkflowRuntime.prepare(stage,r,manifest);progress(stage,state,error,"Checking original software dependencies");LofteeWorkflowRuntime.health(stage,r,runtime,manifest);Path worker=stage.resolve("worker"),cases=Files.createDirectory(worker.resolve("cases"));
                    for(var analysis:r.analyses()){
                        String id=text(analysis.get("id"));progress(stage,state,error,"Running original annotation case "+id);Path home=Files.createDirectory(cases.resolve(id));int code=LofteeWorkflowRuntime.execute(worker,home,id,runtime.command(options(inputs.directory(),home,analysis,r,runtime)),r,runtime,manifest);diagnostics(home,warnings,r);require(code==0,"Original VEP/LOFTEE case failed: "+id+"; inspect complete original logs");var logs=new ArrayList<>(List.of(home.resolve("stdout.log"),home.resolve("stderr.log")));if(Files.exists(home.resolve("original.warnings.txt")))logs.add(home.resolve("original.warnings.txt"));
                        LofteeVcfAudit.Summary summary;
                        try(var variants=Files.newBufferedWriter(home.resolve("native-variants.tsv"),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);var annotations=Files.newBufferedWriter(home.resolve("native-annotations.tsv"),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW)){
                            variants.write("row\tchromosome\tposition\tid\tref\talts\tannotations\ttargets\tHC\tLC\tOS\n");annotations.write("row\tannotation\tallele_number\tchromosome\tposition\tid\tref\talt\tgene\tfeature\tconsequence\tconfidence\tfilters\tflags\tinfo\traw_CSQ\n");
                            summary=LofteeVcfAudit.audit(inputs.directory().resolve(r.inputName()),home.resolve("original.vcf"),logs,LofteeWorkflowRequest.bool(object(analysis.get("settings")).get("run_splice_predictions")),new LofteeVcfAudit.Limits(r.decodedCharacters(),r.variants(),r.annotations(),r.lineCharacters()),v->variants.write(v.row()+"\t"+v.chromosome()+"\t"+v.position()+"\t"+v.id()+"\t"+v.reference()+"\t"+v.alternates()+"\t"+v.annotations()+"\t"+v.targetTranscripts()+"\t"+v.highConfidence()+"\t"+v.lowConfidence()+"\t"+v.otherSplice()+"\n"),a->annotations.write(a.row()+"\t"+a.annotation()+"\t"+a.alleleNumber()+"\t"+a.chromosome()+"\t"+a.position()+"\t"+a.id()+"\t"+a.reference()+"\t"+a.alternate()+"\t"+a.gene()+"\t"+a.feature()+"\t"+a.consequence()+"\t"+a.confidence()+"\t"+a.filters()+"\t"+a.flags()+"\t"+a.info()+"\t"+a.rawCsq()+"\n"));
                        }
                        var report=new LinkedHashMap<String,Object>();report.put("id",id);report.put("variants",summary.variants());report.put("annotations",summary.annotations());report.put("target_transcripts",summary.targetTranscripts());report.put("HC",summary.highConfidence());report.put("LC",summary.lowConfidence());report.put("OS",summary.otherSplice());report.put("flagged_annotations",summary.flaggedAnnotations());report.put("unclassified_annotations",summary.unclassifiedAnnotations());report.put("CSQ_fields",summary.csqFields());report.put("original_settings",analysis);report.put("native_calibration_or_transcript_selection_inferred",false);NextflowFiles.writeJson(home.resolve("native-audit.json"),report);reports.add(report);
                        if(summary.targetTranscripts()==0)warnings.add("CASE "+id+": no original eligible target transcript was returned. The complete source output is retained; this is not evidence of benign function or complete transcript coverage.");if(summary.flaggedAnnotations()>0)warnings.add("CASE "+id+": original flags are retained on "+summary.flaggedAnnotations()+" annotations; flags do not automatically convert HC to LC.");
                        if(!LofteeWorkflowRequest.bool(analysis.get("ancestral_check")))warnings.add("CASE "+id+": ancestral checking is explicitly disabled; no ancestral-state exclusion is claimed.");if(!LofteeWorkflowRequest.bool(analysis.get("conservation_check")))warnings.add("CASE "+id+": optional conservation/PhyloCSF checking is explicitly disabled; those flags are unavailable, not negative findings.");LofteeWorkflowRuntime.finalCapacity(worker,r);
                    }
                    progress(stage,state,error,"Rechecking every input and runtime file before result admission");inputs.verify();runtime.verify();require(requestPin.equals(NextflowFiles.pin(requestPath,1048576,()->{})),"Request changed during execution");var provenance=new LinkedHashMap<String,Object>();provenance.put("reference_origin",r.referenceOrigin());provenance.put("resources",r.effective());provenance.put("analyses",reports);provenance.put("native_input_audit",inputs.inspection());provenance.put("original_labels_are_caller_assertions",true);provenance.put("historical_paper_image_or_full_pipeline_reproduced",false);NextflowFiles.writeJson(stage.resolve("provenance.json"),provenance);progress(stage,state,error,"Publishing verified complete results");Path results=Files.createDirectory(stage.resolve("results"));
                    for(var analysis:r.analyses()){String id=text(analysis.get("id"));Path destination=Files.createDirectory(results.resolve(id)),original=cases.resolve(id);for(String name:List.of("original.vcf","native-variants.tsv","native-annotations.tsv","native-audit.json")){Path file=original.resolve(name);var pin=NextflowFiles.pin(file,r.outputBytes(),()->{});Files.copy(file,destination.resolve(name));require(pin.equals(NextflowFiles.pin(destination.resolve(name),r.outputBytes(),()->{})),"Result publication changed original/native bytes");}}
                    LofteeWorkflowRuntime.publishedCapacity(stage,r);state.put("status","PASS_ORIGINAL_VEP_LOFTEE_WORKFLOW");state.put("result_admitted",true);state.put("analyses",reports.size());exit[0]=0;
                }catch(LofteeWorkflowRuntime.Unavailable failure){exit[0]=reports.isEmpty()?3:2;state.put("status",exit[0]==3?"SKIP3_DEPENDENCY_UNAVAILABLE":"FAIL2_RUNTIME_FAILED_AFTER_PRIOR_CASE");state.put("cause",failure.toString());warnings.add((exit[0]==3?"SKIP3 DEPENDENT ANALYSIS SKIPPED: ":"FAIL2 ATOMIC BATCH UNADMITTED AFTER PRIOR CASE: ")+failure);quarantine(stage);}
                catch(Exception failure){exit[0]=2;state.put("status","FAIL2_NO_RESULT_ADMITTED");state.put("cause",failure.toString());warnings.add("FAIL2: "+failure);quarantine(stage);}
                catch(OutOfMemoryError failure){exit[0]=2;state.put("status","FAIL2_NO_RESULT_ADMITTED");state.put("cause","Java heap exhausted");warnings.add("FAIL2: Java heap exhausted; preserve inputs/provisional ledgers and retry NEW paths with permitted heap/capacities without omitting data.");quarantine(stage);}
                if(exit[0]!=0)state.put("result_admitted",false);writeStatus(stage,state);Files.writeString(stage.resolve("WARNINGS.md"),"# "+state.get("status")+"\n\n"+String.join("\n\n",warnings)+"\n\nREQUIRED ACTION: "+ACTION+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);manifest.put("result_admitted",state.get("result_admitted"));manifest.put("scope","unchanged-original-VEP105-LOFTEE-with-native-input-and-complete-returned-family-audits");manifest.put("runtime_environment_fallback",false);
            });emit(exit[0]==0?output:error,(exit[0]==0?"Original VEP/LOFTEE workflow admitted: ":exit[0]==3?"SKIP3 DEPENDENT ANALYSIS SKIPPED: ":"FAIL2 NO RESULT ADMITTED: ")+out);emit(error,"WARNINGS / REQUIRED ACTIONS: "+out.resolve("WARNINGS.md")+"\n"+ACTION);return exit[0];
        }catch(Exception failure){emit(error,"FAIL2 NO RESULT ADMITTED: "+failure+"\n"+ACTION);return 2;}
    }
    static List<String> options(Path inputs,Path home,Map<String,Object> a,LofteeWorkflowRequest.Request r,LofteeWorkflowRuntime.Prepared runtime)throws IOException {
        var result=new ArrayList<String>(List.of("--input_file",inputs.resolve(r.inputName()).toString(),"--output_file",home.resolve("original.vcf").toString(),"--format","vcf","--vcf","--fasta",inputs.resolve(r.fastaName("reference",r.fasta())).toString(),"--species","homo_sapiens","--assembly",text(r.fasta().get("assembly_label")),"--no_stats","--allele_number","--biotype","--numbers","--symbol","--canonical","--mane","--check_ref","--buffer_size",Integer.toString(r.bufferSize()),"--dir_plugins",runtime.source().toString(),"--warning_file",home.resolve("original.warnings.txt").toString()));
        if(r.transcripts().get("kind").equals("gtf"))Collections.addAll(result,"--gtf",inputs.resolve("genes.gtf.gz").toString());else Collections.addAll(result,"--offline","--cache","--dir_cache",inputs.resolve("cache").toString(),"--cache_version","105");if(r.threads()>1)Collections.addAll(result,"--fork",Integer.toString(r.threads()));
        var settings=object(a.get("settings"));var plugin=new ArrayList<String>();plugin.add("LoF");plugin.add("loftee_path:"+runtime.source());plugin.add("human_ancestor_fa:"+(LofteeWorkflowRequest.bool(a.get("ancestral_check"))?inputs.resolve(r.fastaName("ancestor",r.ancestor())).toString():"false"));plugin.add("conservation_file:"+(LofteeWorkflowRequest.bool(a.get("conservation_check"))?inputs.resolve("conservation.sqlite").toString():"false"));plugin.add("check_complete_cds:false");boolean weighted=LofteeWorkflowRequest.bool(settings.get("use_gerp_end_trunc"));if(weighted)plugin.add("gerp_bigwig:"+inputs.resolve("gerp.bw"));
        for(var e:new TreeMap<>(settings).entrySet()){
            String key=e.getKey();if(weighted&&key.equals("filter_position")||!weighted&&key.equals("gerp_end_trunc_cutoff"))continue;Object value=e.getValue();String encoded=value instanceof Boolean b?(key.equals("apply_all")?Boolean.toString(b):b?"1":"0"):value.toString();plugin.add(key+":"+encoded);
        }
        Collections.addAll(result,"--plugin",String.join(",",plugin));return result;
    }
    private static void diagnostics(Path home,List<String> warnings,LofteeWorkflowRequest.Request r)throws IOException {
        long count=0;for(String name:List.of("stdout.log","stderr.log","original.warnings.txt")){Path file=home.resolve(name);if(!Files.exists(file))continue;try(var lines=new LofteeWorkflowInputs.Lines(file,false,r.lineCharacters(),r.decodedCharacters(),new long[]{0})){for(String line;(line=lines.next())!=null;){String lower=line.toLowerCase(Locale.ROOT);if((lower.contains("faidx")||lower.contains("samtools"))&&(lower.contains("failed")||lower.contains("error")||lower.contains("not found")||lower.contains("invalid")||lower.contains("not present")))throw new IOException("Original ancestral/reference command failed: "+line);if(lower.contains("warning")||lower.contains("error")||lower.contains("experimental")){count++;if(count<=1000)warnings.add("ORIGINAL LOG ["+home.getFileName()+"/"+name+"]: "+line);}}}}
        if(count>1000)warnings.add("Only the first1000 original diagnostics are summarized here; all "+count+" matching messages and complete original log bytes remain in the named worker log files. Inspect those files before use.");
    }
    @FunctionalInterface private interface Job {void execute(Path stage,Map<String,Object> manifest)throws Exception;}
    private static void transaction(Path destination,Job job)throws Exception {
        Files.createDirectories(destination.getParent());Path stage=Files.createTempDirectory(destination.getParent(),".loftee-attempt-");var manifest=new LinkedHashMap<String,Object>();manifest.put("schema_version",1);manifest.put("operation","original-VEP-LOFTEE-development");manifest.put("started_at",Instant.now().toString());
        try{job.execute(stage,manifest);var files=new TreeMap<String,Object>();try(var walk=Files.walk(stage)){for(Path file:walk.filter(Files::isRegularFile).toList()){var value=NextflowFiles.pin(file,Long.MAX_VALUE,()->{});files.put(stage.relativize(file).toString().replace('\\','/'),Map.of("bytes",value.bytes(),"sha256",value.sha256()));}}manifest.put("outputs",files);manifest.put("completed_at",Instant.now().toString());NextflowFiles.writeJson(stage.resolve("manifest.json"),manifest);Files.move(stage,destination);}
        catch(Exception failure){retain(stage,failure);throw new IOException("No result admitted; complete owned attempt retained at "+stage,failure);}catch(Error failure){retain(stage,failure);throw failure;}
    }
    private static void progress(Path stage,Map<String,Object> state,PrintStream error,String phase)throws IOException{state.put("phase",phase);writeStatus(stage,state);emit(error,"LOFTEE: "+phase+"; no result admitted until the complete batch passes.");}
    private static void writeStatus(Path stage,Map<String,Object> value)throws IOException{Files.writeString(stage.resolve("analysis-status.json"),NextflowJson.json(value)+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING);}
    private static void quarantine(Path stage)throws IOException{if(Files.exists(stage.resolve("results")))Files.move(stage.resolve("results"),stage.resolve("unadmitted-partial-results"));}
    private static void retain(Path stage,Throwable failure){try{quarantine(stage);writeStatus(stage,Map.of("status","FAIL2_ATTEMPT_OR_PUBLICATION_FAILED","result_admitted",false,"cause",failure.toString(),"required_action",ACTION));Path file=stage.resolve("WARNINGS.md");String prior=Files.exists(file)?Files.readString(file):"";Files.writeString(file,"# FAIL2 NO RESULT ADMITTED\n\n"+failure+"\n\nOWNED ATTEMPT RETAINED AT: "+stage+"\n\nREQUIRED ACTION: "+ACTION+"\n\n"+prior);}catch(Exception recording){failure.addSuppressed(recording);}}
    private static Path resolved(Path path)throws IOException {var missing=new ArrayDeque<Path>();Path current=path.toAbsolutePath().normalize();while(!Files.exists(current,LinkOption.NOFOLLOW_LINKS)){require(current.getParent()!=null,"No existing path ancestor");missing.addFirst(current.getFileName());current=current.getParent();}current=current.toRealPath();for(Path name:missing)current=current.resolve(name);return current.normalize();}
    private static void emit(PrintStream stream,String text){byte[] raw=(text+"\n").getBytes(StandardCharsets.UTF_8);stream.write(raw,0,raw.length);stream.flush();}
}
